        style={{ fontFamily: "var(--font-typewriter)" }}
      >
        Insert {props.query ? `“${props.query}”` : "a block"}
      </p>

      {candidates.length === 0 ? (
        <p
          class="px-3 py-5 text-center text-sm text-[var(--color-ink-muted)]"
          style={{ fontFamily: "var(--font-serif)" }}
        >
