## rtk read convex/images.ts
/**
 * Durable storage records for images embedded in manuscripts.
 *
 * The upload is intentionally a two-step flow:
 *  1. `generateUploadUrl` authenticates the caller and preflights the file.
 *  2. The client uploads to Convex, then calls `saveImage` with the returned
 *     storage id. `saveImage` validates Convex's authoritative metadata before
 *     recording ownership.
 *
 * No public function accepts an owner id. Ownership always comes from the
 * authenticated Convex identity.
 */

import { v } from "convex/values";
import type { Doc } from "./_generated/dataModel";
import type { QueryCtx } from "./_generated/server";
import { mutation, query } from "./_generated/server";

export const MAX_IMAGE_SIZE_BYTES = 10 * 1024 * 1024;

export const SUPPORTED_IMAGE_CONTENT_TYPES = [
  "image/gif",
  "image/jpeg",
  "image/png",
  "image/webp",
] as const;

type SupportedImageContentType = (typeof SUPPORTED_IMAGE_CONTENT_TYPES)[number];

const supportedContentTypes = new Set<string>(SUPPORTED_IMAGE_CONTENT_TYPES);
const imageContentTypeValidator = v.union(
  v.literal("image/gif"),
  v.literal("image/jpeg"),
  v.literal("image/png"),
  v.literal("image/webp"),
);

const imageResultValidator = v.object({
  imageId: v.id("images"),
  folioId: v.string(),
  url: v.string(),
  contentType: imageContentTypeValidator,
  size: v.number(),
  createdAt: v.number(),
});

async function requireOwnerId(ctx: Pick<QueryCtx, "auth">): Promise<string> {
  const identity = await ctx.auth.getUserIdentity();
  if (!identity) throw new Error("Not signed in");
  return identity.tokenIdentifier;
}

function normalizeContentType(contentType: string): string {
  return contentType.split(";", 1)[0]?.trim().toLowerCase() ?? "";
}

export function validateImageMetadata(
  contentType: string | undefined,
  size: number,
): SupportedImageContentType {
  const normalized = normalizeContentType(contentType ?? "");
  if (!supportedContentTypes.has(normalized)) {
    throw new Error("Unsupported image type");
  }
  if (!Number.isSafeInteger(size) || size <= 0) {
    throw new Error("Image size must be a positive integer");
  }
  if (size > MAX_IMAGE_SIZE_BYTES) {
    throw new Error("Image exceeds the 10 MB limit");
  }
  return normalized as SupportedImageContentType;
}

async function serializeImage(
  ctx: Pick<QueryCtx, "storage">,
  image: Doc<"images">,
) {
  const url = await ctx.storage.getUrl(image.storageId);
  if (!url) throw new Error("Image file not found");
  return {
    imageId: image._id,
    folioId: image.folioId,
    url,
    contentType: image.contentType,
    size: image.size,
    createdAt: image.createdAt,
  };
}

/** Mint a short-lived Convex upload URL after authenticating and preflighting. */
export const generateUploadUrl = mutation({
  args: {
    contentType: v.string(),
    size: v.number(),
  },
  returns: v.object({ uploadUrl: v.string() }),
  handler: async (ctx, args) => {
    await requireOwnerId(ctx);
    validateImageMetadata(args.contentType, args.size);
    return { uploadUrl: await ctx.storage.generateUploadUrl() };
  },
});

/**
 * Register an uploaded blob as an image owned by the authenticated caller.
 * The authoritative content type and size come from Convex's system table,
 * never from client arguments.
 */
export const saveImage = mutation({
  args: {
    folioId: v.string(),
    storageId: v.id("_storage"),
  },
  returns: imageResultValidator,
  handler: async (ctx, args) => {
    const ownerId = await requireOwnerId(ctx);
    const metadata = await ctx.db.system.get("_storage", args.storageId);
    if (!metadata) throw new Error("Uploaded image not found");

    const contentType = validateImageMetadata(
      metadata.contentType,
      metadata.size,
    );

    const existing = await ctx.db
      .query("images")
      .withIndex("by_storageId", (q) => q.eq("storageId", args.storageId))
      .unique();
    if (existing) {
      if (existing.ownerId !== ownerId) {
        throw new Error("Image not found");
      }
      return await serializeImage(ctx, existing);
    }

    const createdAt = Date.now();
    const imageId = await ctx.db.insert("images", {
      ownerId,
      folioId: args.folioId,
      storageId: args.storageId,
      contentType,
      size: metadata.size,
      createdAt,
    });

    const url = await ctx.storage.getUrl(args.storageId);
    if (!url) throw new Error("Uploaded image not found");
    return {
      imageId,
      folioId: args.folioId,
      url,
      contentType,
      size: metadata.size,
      createdAt,
    };
  },
});

/** Resolve an owned image to its current signed storage URL. */
export const getImage = query({
  args: { imageId: v.id("images") },
  returns: v.union(imageResultValidator, v.null()),
  handler: async (ctx, args) => {
    const ownerId = await requireOwnerId(ctx);
    const image = await ctx.db.get("images", args.imageId);
    if (!image || image.ownerId !== ownerId) return null;
    return await serializeImage(ctx, image);
  },
});

/** Delete both the owned metadata row and its underlying Convex blob. */
export const deleteImage = mutation({
  args: { imageId: v.id("images") },
  returns: v.null(),
  handler: async (ctx, args) => {
    const ownerId = await requireOwnerId(ctx);
    const image = await ctx.db.get("images", args.imageId);
    if (!image || image.ownerId !== ownerId) {
      throw new Error("Image not found");
    }
    await ctx.storage.delete(image.storageId);
    await ctx.db.delete("images", image._id);
    return null;
  },
});

## rtk read convex/images.test.ts
import { describe, expect, test } from "bun:test";
import {
  MAX_IMAGE_SIZE_BYTES,
  deleteImage,
  generateUploadUrl,
  getImage,
  saveImage,
} from "./images";

type ImageRow = {
  _id: string;
  _creationTime: number;
  ownerId: string;
  folioId: string;
  storageId: string;
  contentType: string;
  size: number;
  createdAt: number;
};

type StorageMetadata = {
  _id: string;
  _creationTime: number;
  contentType?: string;
  sha256: string;
  size: number;
};

function makeCtx(
  options: {
    identity?: string | null;
    images?: ImageRow[];
    storage?: StorageMetadata[];
  } = {},
) {
  const images = [...(options.images ?? [])];
  const storage = new Map(
    (options.storage ?? []).map((metadata) => [metadata._id, metadata]),
  );
  const generatedUploadUrls: string[] = [];
  const deletedRows: string[] = [];
  const deletedStorage: string[] = [];

  const ctx = {
    auth: {
      getUserIdentity: async () =>
        options.identity === null
          ? null
          : { tokenIdentifier: options.identity ?? "owner-a" },
    },
    db: {
      system: {
        get: async (_table: string, storageId: string) =>
          storage.get(storageId) ?? null,
      },
      get: async (_table: string, imageId: string) =>
        images.find((image) => image._id === imageId) ?? null,
      query: () => ({
        withIndex: (
          _name: string,
          applyIndex: (q: {
            eq: (field: string, value: unknown) => unknown;
          }) => unknown,
        ) => {
          let storageId: unknown;
          const q = {
            eq: (field: string, value: unknown) => {
              if (field === "storageId") storageId = value;
              return q;
            },
          };
          applyIndex(q);
          return {
            unique: async () =>
              images.find((image) => image.storageId === storageId) ?? null,
          };
        },
      }),
      insert: async (
        _table: string,
        value: Omit<ImageRow, "_id" | "_creationTime">,
      ) => {
        const imageId = `image-${images.length + 1}`;
        images.push({ _id: imageId, _creationTime: Date.now(), ...value });
        return imageId;
      },
      delete: async (_table: string, imageId: string) => {
        deletedRows.push(imageId);
        const index = images.findIndex((image) => image._id === imageId);
        if (index >= 0) images.splice(index, 1);
      },
    },
    storage: {
      generateUploadUrl: async () => {
        const url = "https://upload.example.test/image";
        generatedUploadUrls.push(url);
        return url;
      },
      getUrl: async (storageId: string) =>
        storage.has(storageId)
          ? `https://files.example.test/${storageId}`
          : null,
      delete: async (storageId: string) => {
        deletedStorage.push(storageId);
        storage.delete(storageId);
      },
    },
    images,
    generatedUploadUrls,
    deletedRows,
    deletedStorage,
  };

  return ctx;
}

/** Reach the internal handler on a registered Convex function. */
function handler<T>(fn: unknown): T {
  return (fn as { _handler: T })._handler;
}

const pngStorage: StorageMetadata = {
  _id: "storage-png",
  _creationTime: 1,
  contentType: "image/png",
  sha256: "sha256",
  size: 1024,
};

const ownedImage: ImageRow = {
  _id: "image-owned",
  _creationTime: 1,
  ownerId: "owner-a",
  folioId: "folio-a",
  storageId: pngStorage._id,
  contentType: "image/png",
  size: pngStorage.size,
  createdAt: 2,
};

describe("image upload security", () => {
  test("requires auth before generating an upload URL", async () => {
    const ctx = makeCtx({ identity: null });

    await expect(
      handler<
        (
          ctx: unknown,
          args: { contentType: string; size: number },
        ) => Promise<unknown>
      >(generateUploadUrl)(ctx as never, {
        contentType: "image/png",
        size: 1024,
      }),
    ).rejects.toThrow("Not signed in");
    expect(ctx.generatedUploadUrls).toHaveLength(0);
  });

  test("rejects unsupported declarations and oversized upload requests", async () => {
    const ctx = makeCtx();
    const generate =
      handler<
        (
          ctx: unknown,
          args: { contentType: string; size: number },
        ) => Promise<unknown>
      >(generateUploadUrl);

    await expect(
      generate(ctx as never, { contentType: "image/svg+xml", size: 1024 }),
    ).rejects.toThrow("Unsupported image type");
    await expect(
      generate(ctx as never, {
        contentType: "image/png",
        size: MAX_IMAGE_SIZE_BYTES + 1,
      }),
    ).rejects.toThrow("10 MB");
    expect(ctx.generatedUploadUrls).toHaveLength(0);
  });

  test("validates stored metadata and derives record ownership from auth", async () => {
    const ctx = makeCtx({
      identity: "authenticated-owner",
      storage: [pngStorage],
    });

    const result = await handler<
      (
        ctx: unknown,
        args: { folioId: string; storageId: string },
      ) => Promise<{ imageId: string; url: string }>
    >(saveImage)(ctx as never, {
      folioId: "folio-a",
      storageId: pngStorage._id,
    });

    expect(ctx.images[0]).toMatchObject({
      ownerId: "authenticated-owner",
      folioId: "folio-a",
      storageId: pngStorage._id,
      contentType: "image/png",
      size: pngStorage.size,
    });
    expect(result).toMatchObject({
      imageId: "image-1",
      url: `https://files.example.test/${pngStorage._id}`,
    });
  });

  test("rejects unsupported and oversized blobs using authoritative metadata", async () => {
    const svg = {
      ...pngStorage,
      _id: "storage-svg",
      contentType: "image/svg+xml",
    };
    const huge = {
      ...pngStorage,
      _id: "storage-huge",
      size: MAX_IMAGE_SIZE_BYTES + 1,
    };
    const ctx = makeCtx({ storage: [svg, huge] });
    const save =
      handler<
        (
          ctx: unknown,
          args: { folioId: string; storageId: string },
        ) => Promise<unknown>
      >(saveImage);

    await expect(
      save(ctx as never, { folioId: "folio-a", storageId: svg._id }),
    ).rejects.toThrow("Unsupported image type");
    await expect(
      save(ctx as never, { folioId: "folio-a", storageId: huge._id }),
    ).rejects.toThrow("10 MB");
    expect(ctx.images).toHaveLength(0);
  });

  test("does not allow another user to claim an existing storage id", async () => {
    const ctx = makeCtx({
      identity: "owner-b",
      images: [ownedImage],
      storage: [pngStorage],
    });

    await expect(
      handler<
        (
          ctx: unknown,
          args: { folioId: string; storageId: string },
        ) => Promise<unknown>
      >(saveImage)(ctx as never, {
        folioId: "folio-b",
        storageId: pngStorage._id,
      }),
    ).rejects.toThrow("Image not found");
  });
});

describe("image lookup and deletion ownership", () => {
  test("returns a fresh signed URL to the image owner", async () => {
    const ctx = makeCtx({ images: [ownedImage], storage: [pngStorage] });

    const result = await handler<
      (
        ctx: unknown,
        args: { imageId: string },
      ) => Promise<{ imageId: string; url: string }>
    >(getImage)(ctx as never, { imageId: ownedImage._id });

    expect(result).toMatchObject({
      imageId: ownedImage._id,
      url: `https://files.example.test/${pngStorage._id}`,
    });
  });

  test("hides an image from a different authenticated user", async () => {
    const ctx = makeCtx({
      identity: "owner-b",
      images: [ownedImage],
      storage: [pngStorage],
    });

    const result = await handler<
      (ctx: unknown, args: { imageId: string }) => Promise<unknown>
    >(getImage)(ctx as never, { imageId: ownedImage._id });

    expect(result).toBeNull();
  });

  test("rejects cross-owner deletion without touching metadata or storage", async () => {
    const ctx = makeCtx({
      identity: "owner-b",
      images: [ownedImage],
      storage: [pngStorage],
    });

    await expect(
      handler<(ctx: unknown, args: { imageId: string }) => Promise<unknown>>(
        deleteImage,
      )(ctx as never, { imageId: ownedImage._id }),
    ).rejects.toThrow("Image not found");
    expect(ctx.deletedRows).toHaveLength(0);
    expect(ctx.deletedStorage).toHaveLength(0);
  });

  test("owner deletion removes both the file and durable record", async () => {
    const ctx = makeCtx({ images: [ownedImage], storage: [pngStorage] });

    const result = await handler<
      (ctx: unknown, args: { imageId: string }) => Promise<unknown>
    >(deleteImage)(ctx as never, { imageId: ownedImage._id });

    expect(result).toBeNull();
    expect(ctx.deletedStorage).toEqual([pngStorage._id]);
    expect(ctx.deletedRows).toEqual([ownedImage._id]);
    expect(ctx.images).toHaveLength(0);
  });
});

