## rtk read vitest.config.ts
import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    environment: "edge-runtime",
  },
});

## rtk proxy sed -n '1,260p' convex/images.test.ts
/// <reference types="vite/client" />

import { convexTest } from "convex-test";
import { makeFunctionReference } from "convex/server";
import { describe, expect, test } from "vitest";
import type { Id } from "./_generated/dataModel";
import { MAX_IMAGE_SIZE_BYTES } from "./images";
import schema from "./schema";

const modules = import.meta.glob("./**/*.ts");

type ImageResult = {
  imageId: Id<"images">;
  folioId: string;
  url: string;
  contentType: "image/gif" | "image/jpeg" | "image/png" | "image/webp";
  size: number;
  createdAt: number;
};

const imagesApi = {
  generateUploadUrl: makeFunctionReference<
    "mutation",
    { contentType: string; size: number },
    { uploadUrl: string }
  >("images:generateUploadUrl"),
  saveImage: makeFunctionReference<
    "mutation",
    { folioId: string; storageId: Id<"_storage"> },
    ImageResult
  >("images:saveImage"),
  getImage: makeFunctionReference<
    "query",
    { imageId: Id<"images"> },
    ImageResult | null
  >("images:getImage"),
  deleteImage: makeFunctionReference<
    "mutation",
    { imageId: Id<"images"> },
    null
  >("images:deleteImage"),
};

const ownerAIdentity = { tokenIdentifier: "test-issuer|owner-a" };
const ownerBIdentity = { tokenIdentifier: "test-issuer|owner-b" };

function setup() {
  const t = convexTest(schema, modules);
  return {
    t,
    ownerA: t.withIdentity(ownerAIdentity),
    ownerB: t.withIdentity(ownerBIdentity),
  };
}

type TestHarness = ReturnType<typeof setup>["t"];

/**
 * `convex-test` stores a real Blob but currently omits its MIME type from the
 * mock `_storage` row. Patch that system field so production metadata checks
 * receive the same shape Convex provides after an HTTP upload.
 */
async function storeImage(
  t: TestHarness,
  contentType: string,
  size: number,
): Promise<Id<"_storage">> {
  return await t.run(async (ctx) => {
    const storageId = await ctx.storage.store(
      new Blob([new Uint8Array(size)], { type: contentType }),
    );
    const systemWriter = ctx.db as unknown as {
      patch: (
        table: "_storage",
        id: Id<"_storage">,
        value: { contentType: string },
      ) => Promise<void>;
    };
    await systemWriter.patch("_storage", storageId, { contentType });
    return storageId;
  });
}

describe("image upload validation", () => {
  test("rejects unauthenticated upload URL requests", async () => {
    const { t } = setup();

    await expect(
      t.mutation(imagesApi.generateUploadUrl, {
        contentType: "image/png",
        size: 1024,
      }),
    ).rejects.toThrow("Not signed in");
  });

  test("rejects unsupported and oversized upload declarations", async () => {
    const { ownerA } = setup();

    await expect(
      ownerA.mutation(imagesApi.generateUploadUrl, {
        contentType: "image/svg+xml",
        size: 1024,
      }),
    ).rejects.toThrow("Unsupported image type");
    await expect(
      ownerA.mutation(imagesApi.generateUploadUrl, {
        contentType: "image/png",
        size: MAX_IMAGE_SIZE_BYTES + 1,
      }),
    ).rejects.toThrow("10 MB");
  });

  test("returns an upload URL for an authenticated supported image", async () => {
    const { ownerA } = setup();

    const result = await ownerA.mutation(imagesApi.generateUploadUrl, {
      contentType: "image/png",
      size: 1024,
    });

    expect(result.uploadUrl).toContain("/api/storage/upload?token=");
  });

  test("rejects unsupported and oversized authoritative storage metadata", async () => {
    const { t, ownerA } = setup();
    const svgStorageId = await storeImage(t, "image/svg+xml", 1024);
    const hugeStorageId = await storeImage(
      t,
      "image/png",
      MAX_IMAGE_SIZE_BYTES + 1,
    );

    await expect(
      ownerA.mutation(imagesApi.saveImage, {
        folioId: "folio-a",
        storageId: svgStorageId,
      }),
    ).rejects.toThrow("Unsupported image type");
    await expect(
      ownerA.mutation(imagesApi.saveImage, {
        folioId: "folio-a",
        storageId: hugeStorageId,
      }),
    ).rejects.toThrow("10 MB");

    const rows = await t.run((ctx) => ctx.db.query("images").take(10));
    expect(rows).toEqual([]);
  });
});

describe("image ownership", () => {
  test("owner can save, resolve, and delete an image and its blob", async () => {
    const { t, ownerA } = setup();
    const storageId = await storeImage(t, "image/png", 1024);

    const saved = await ownerA.mutation(imagesApi.saveImage, {
      folioId: "folio-a",
      storageId,
    });
    expect(saved).toMatchObject({
      folioId: "folio-a",
      contentType: "image/png",
      size: 1024,
    });

    const storedRows = await t.run((ctx) =>
      ctx.db
        .query("images")
        .withIndex("by_ownerId", (q) =>
          q.eq("ownerId", ownerAIdentity.tokenIdentifier),
        )
        .take(10),
    );
    expect(storedRows).toHaveLength(1);
    expect(storedRows[0]).toMatchObject({
      ownerId: ownerAIdentity.tokenIdentifier,
      folioId: "folio-a",
      storageId,
    });

    const resolved = await ownerA.query(imagesApi.getImage, {
      imageId: saved.imageId,
    });
    expect(resolved).toMatchObject({
      imageId: saved.imageId,
      folioId: "folio-a",
      contentType: "image/png",
    });
    expect(resolved?.url).toMatch(
      /^https:\/\/some-deployment\.convex\.cloud\/api\/storage\/.+$/,
    );

    await expect(
      ownerA.mutation(imagesApi.deleteImage, { imageId: saved.imageId }),
    ).resolves.toBeNull();

    const deleted = await t.run(async (ctx) => ({
      row: await ctx.db.get("images", saved.imageId),
      metadata: await ctx.db.system.get("_storage", storageId),
      blob: await ctx.storage.get(storageId),
    }));
    expect(deleted).toEqual({ row: null, metadata: null, blob: null });
  });

  test("cross-owner claim, lookup, and deletion are denied", async () => {
    const { t, ownerA, ownerB } = setup();
    const storageId = await storeImage(t, "image/webp", 2048);
    const saved = await ownerA.mutation(imagesApi.saveImage, {
      folioId: "folio-a",
      storageId,
    });

    await expect(
      ownerB.mutation(imagesApi.saveImage, {
        folioId: "folio-b",
        storageId,
      }),
    ).rejects.toThrow("Image not found");
    await expect(
      ownerB.query(imagesApi.getImage, { imageId: saved.imageId }),
    ).resolves.toBeNull();
    await expect(
      ownerB.mutation(imagesApi.deleteImage, { imageId: saved.imageId }),
    ).rejects.toThrow("Image not found");

    const ownerResult = await ownerA.query(imagesApi.getImage, {
      imageId: saved.imageId,
    });
    expect(ownerResult?.imageId).toBe(saved.imageId);
    const metadata = await t.run((ctx) =>
      ctx.db.system.get("_storage", storageId),
    );
    expect(metadata).not.toBeNull();
  });
});

import type { Editor, NodeViewRendererProps } from "@tiptap/core";
import type { Node as ProseMirrorNode } from "@tiptap/pm/model";
import type { NodeView } from "@tiptap/pm/view";
import { EndnoteNode } from "./endnote-node";
import {
  adjacentInlineNote,
  collectInlineNotes,
  convertInlineNote,
  deleteInlineNote,
  focusInlineNoteReference,
  normalizeInlineNoteKind,
  updateInlineNote,
  type InlineNoteKind,
} from "../note-editing";

function button(label: string): HTMLButtonElement {
  const element = document.createElement("button");
  element.type = "button";
  element.textContent = label;
  return element;
}

function stylePopover(element: HTMLElement): void {
  Object.assign(element.style, {
    position: "fixed",
    zIndex: "80",
    width: "min(22rem, calc(100vw - 2rem))",
    padding: "0.8rem",
    border: "1px solid var(--color-paper-3, #d2c8b5)",
    borderRadius: "4px",
    background: "var(--color-paper, #fffdf8)",
    color: "var(--color-ink, #221f1a)",
    boxShadow: "0 12px 36px rgb(0 0 0 / 0.18)",
    fontFamily: "var(--font-typewriter, monospace)",
  });
}

function positionPopover(popover: HTMLElement, marker: HTMLElement): void {
  const rect = marker.getBoundingClientRect();
  const width = Math.min(352, Math.max(240, window.innerWidth - 32));
  const height = popover.getBoundingClientRect().height || 260;
  const left = Math.max(
    16,
    Math.min(rect.left, Math.max(16, window.innerWidth - width - 16)),
  );
  const below = rect.bottom + 8;
  const above = rect.top - height - 8;
  const top =
    below + height <= window.innerHeight - 16 ? below : Math.max(16, above);

  popover.style.left = `${left}px`;
  popover.style.top = `${top}px`;
  popover.style.maxHeight = `${Math.max(120, window.innerHeight - 32)}px`;
  popover.style.overflowY = "auto";
}

