export class ImageNodeView implements NodeView {
  dom: HTMLElement;

  private node: ProseMirrorNode;
  private readonly props: NodeViewRendererProps;
  private readonly options: ImageNodeOptions;
  private readonly image: HTMLImageElement;
  private readonly caption: HTMLElement;
  private readonly status: HTMLElement;
  private readonly retry: HTMLButtonElement;
  private readonly leftHandle: HTMLButtonElement;
  private readonly rightHandle: HTMLButtonElement;
  private cleanupResize: (() => void) | null = null;

  constructor(props: NodeViewRendererProps, options: ImageNodeOptions) {
    this.props = props;
    this.node = props.node;
    this.options = options;
    this.dom = document.createElement("figure");
    this.dom.className = "twyne-image-node";
    this.dom.setAttribute("contenteditable", "false");
    this.dom.tabIndex = 0;

    this.image = document.createElement("img");
    this.image.draggable = false;
    this.image.addEventListener("load", this.rememberAspectRatio);

    this.caption = document.createElement("figcaption");
    this.caption.className = "twyne-image-caption";

    this.status = document.createElement("div");
    this.status.className = "twyne-image-upload-status";
    this.status.setAttribute("role", "status");
    Object.assign(this.status.style, {
      position: "absolute",
      inset: "auto 0 0 0",
      padding: "0.4rem 0.55rem",
      background: "rgb(20 18 15 / 0.82)",
      color: "white",
      fontSize: "0.72rem",
    });

    this.retry = document.createElement("button");
    this.retry.type = "button";
    this.retry.textContent = "Retry upload";
    this.retry.dataset.imageRetry = "true";
    this.retry.addEventListener("click", this.retryUpload);
    Object.assign(this.retry.style, {
      marginLeft: "0.5rem",
      textDecoration: "underline",
      color: "inherit",
    });

    this.leftHandle = this.createResizeHandle("left");
    this.rightHandle = this.createResizeHandle("right");
    this.dom.append(
      this.image,
      this.caption,
      this.status,
      this.leftHandle,
      this.rightHandle,
    );
    Object.assign(this.dom.style, {
      position: "relative",
      boxSizing: "border-box",
    });
    this.render();
  }

  update(node: ProseMirrorNode): boolean {
    if (node.type !== this.node.type) return false;
    this.node = node;
    this.render();
    return true;
  }

  selectNode(): void {
    this.dom.classList.add("ProseMirror-selectednode");
    this.leftHandle.hidden = false;
    this.rightHandle.hidden = false;
  }

  deselectNode(): void {
    this.dom.classList.remove("ProseMirror-selectednode");
    this.leftHandle.hidden = true;
    this.rightHandle.hidden = true;
  }

  stopEvent(event: Event): boolean {
    const target = event.target;
    return target instanceof globalThis.Node && target !== this.image;
  }

  ignoreMutation(): boolean {
    return true;
  }

  destroy(): void {
    this.cleanupResize?.();
    this.image.removeEventListener("load", this.rememberAspectRatio);
    this.retry.removeEventListener("click", this.retryUpload);
  }

  private readonly rememberAspectRatio = () => {
    if (Number(this.node.attrs.aspectRatio) > 0) return;
    if (this.image.naturalWidth <= 0 || this.image.naturalHeight <= 0) return;
    updateNodeAttributes(this.props, this.node, {
      aspectRatio: this.image.naturalWidth / this.image.naturalHeight,
    });
  };

  private readonly retryUpload = () => {
    const uploadId = this.node.attrs.uploadId;
    const adapter = this.options.uploadAdapter;
    if (typeof uploadId !== "string" || !adapter) return;
    void retryImageUpload(
      this.props.editor,
      uploadId,
      adapter,
      undefined,
      this.options.onUploadError,
    );
  };

  private createResizeHandle(edge: "left" | "right"): HTMLButtonElement {
    const handle = document.createElement("button");
    handle.type = "button";
    handle.hidden = true;
    handle.dataset.imageResize = edge;
    handle.setAttribute("aria-label", `Resize image from ${edge} edge`);
    Object.assign(handle.style, {
      position: "absolute",
      bottom: "0.3rem",
      [edge]: "0.3rem",
      width: "0.85rem",
      height: "0.85rem",
      border: "1px solid currentColor",
      borderRadius: "50%",
      background: "var(--color-paper, white)",
      cursor: "ew-resize",
    });
    handle.addEventListener("pointerdown", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const startX = event.clientX;
      const startWidth = normalizeImageWidth(this.node.attrs.width);
      const editorWidth =
        this.props.editor.view.dom.getBoundingClientRect().width ||
        this.props.editor.view.dom.clientWidth ||
        1;
      const move = (moveEvent: PointerEvent) => {
        const width = imageWidthFromPointerDelta(
          startWidth,
          moveEvent.clientX - startX,
          editorWidth,
          edge,
        );
        updateNodeAttributes(this.props, this.node, { width });
      };
      const finish = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", finish);
        this.cleanupResize = null;
      };
      this.cleanupResize?.();
      this.cleanupResize = finish;
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", finish, { once: true });
    });
    return handle;
  }

  private render(): void {
    const attrs = this.node.attrs as ImageNodeAttributes;
    const pending = attrs.uploadId ? pendingUploads.get(attrs.uploadId) : null;
    const visibleSrc = attrs.src || pending?.previewUrl || "";
    const portable = portableFigureAttributes(attrs);
    for (const [name, value] of Object.entries(portable)) {
      if (value == null) this.dom.removeAttribute(name);
      else this.dom.setAttribute(name, String(value));
    }
    this.dom.dataset.aspectRatioLocked = "true";
    if (visibleSrc) this.image.setAttribute("src", visibleSrc);
    else this.image.removeAttribute("src");
    this.image.alt = attrs.alt || "";
    this.image.style.cssText = imageStyle(attrs.aspectRatio);
    this.caption.textContent = attrs.caption || "";
    this.caption.hidden = !attrs.caption;

    if (attrs.uploadStatus === "uploading") {
      this.status.hidden = false;
      this.status.replaceChildren(
        `Uploading image… ${Math.round(normalizedProgress(attrs.uploadProgress) * 100)}%`,
      );
    } else if (attrs.uploadStatus === "failed") {
      this.status.hidden = false;
      this.status.replaceChildren(
        attrs.uploadError || "Upload failed.",
        this.retry,
      );
    } else {
      this.status.hidden = true;
      this.status.replaceChildren();
    }
  }
}

export const ImageNode = Node.create<ImageNodeOptions>({
  name: "image",
  group: "block",
  atom: true,
  draggable: true,
  selectable: true,
  isolating: true,

  addOptions() {
    return { HTMLAttributes: {}, uploadAdapter: null };
  },

  addAttributes() {
    return {
      src: { default: "" },
      alt: { default: "" },
      caption: { default: "" },
      alignment: { default: "center" },
      width: { default: 100 },
      aspectRatio: { default: null },
      imageId: { default: null },
      offline: { default: false },
      uploadId: { default: null },
      uploadStatus: { default: "ready" },
      uploadProgress: { default: 0, rendered: false },
      uploadError: { default: null },
    };
  },

  parseHTML() {
    return [
      {
        tag: 'figure[data-type="image"]',
        getAttrs: (element) => parseImageAttributes(element as HTMLElement),
      },
      {
        tag: "img[src]",
        getAttrs: (element) => parseImageAttributes(element as HTMLElement),
      },
    ];
  },

  renderHTML({ node, HTMLAttributes }) {
    const attrs = node.attrs as ImageNodeAttributes;
    const children: unknown[] = [
      [
        "img",
        {
          src: attrs.src,
          alt: attrs.alt,
          style: imageStyle(attrs.aspectRatio),
        },
      ],
    ];
    if (attrs.caption) children.push(["figcaption", {}, attrs.caption]);
    return [
      "figure",
      mergeAttributes(
        this.options.HTMLAttributes,
        HTMLAttributes,
        portableFigureAttributes(attrs),
      ),
      ...children,
    ] as never;
  },

  renderText({ node }) {
    const attrs = node.attrs as ImageNodeAttributes;
    return attrs.alt ? `[Image: ${attrs.alt}]` : "[Image]";
  },

  addNodeView() {
    return ((props) =>
      new ImageNodeView(props, this.options)) as NodeViewRenderer;
  },

  addProseMirrorPlugins() {
    const adapter = this.options.uploadAdapter;
    if (!adapter) return [];
    const onUploadError = this.options.onUploadError;
    return [
      new Plugin({
        props: {
          handleDrop: (view, event, _slice, moved) => {
            if (moved) return false;
            const files = imageFilesFromList(event.dataTransfer?.files);
            if (files.length === 0) return false;
            event.preventDefault();
            const at = view.posAtCoords({
              left: event.clientX,
              top: event.clientY,
            });
            insertImageFiles(
              this.editor,
              files,
              adapter,
              at?.pos,
              onUploadError,
            );
            return true;
          },
          handlePaste: (_view, event) => {
            const files = imageFilesFromList(event.clipboardData?.files);
            if (files.length === 0) return false;
            event.preventDefault();
            insertImageFiles(
              this.editor,
              files,
              adapter,
              undefined,
              onUploadError,
            );
            return true;
          },
        },
      }),
    ];
  },
});

## image-upload
import type { ConvexClient } from "convex/browser";
import { api } from "../../convex/_generated/api";
import type { Id } from "../../convex/_generated/dataModel";

export const ACCEPTED_IMAGE_TYPES = [
  "image/gif",
  "image/jpeg",
  "image/png",
  "image/webp",
] as const;

export const MAX_IMAGE_UPLOAD_BYTES = 10 * 1024 * 1024;

export type AcceptedImageType = (typeof ACCEPTED_IMAGE_TYPES)[number];
export type ImageUploadPhase =
  | "reading"
  | "requesting-url"
  | "uploading"
  | "saving"
  | "complete";

export interface ImageUploadProgress {
  /** Overall completion in the inclusive range 0..1. */
  progress: number;
  phase: ImageUploadPhase;
}

export interface UploadedImage {
  src: string;
  storage: "convex" | "inline";
  imageId: string | null;
  contentType: AcceptedImageType;
  size: number;
}

export type ImageUploadTransport = (
  uploadUrl: string,
  file: File,
  onProgress: (progress: number) => void,
) => Promise<string>;

type MutationClient = Pick<ConvexClient, "mutation">;

export type ImageUploadAdapterOptions =
  | {
      mode: "online";
      client: MutationClient;
      folioId: string | (() => string);
      transport?: ImageUploadTransport;
    }
  | {
      mode: "offline";
      readDataUrl?: (file: File) => Promise<string>;
    };

export interface ImageUploadAdapter {
  readonly mode: "online" | "offline";
  upload(
    file: File,
    onProgress?: (progress: ImageUploadProgress) => void,
  ): Promise<UploadedImage>;
}

const acceptedImageTypes = new Set<string>(ACCEPTED_IMAGE_TYPES);

export function validateImageFile(file: File): AcceptedImageType {
  const contentType = file.type.trim().toLowerCase();
  if (!acceptedImageTypes.has(contentType)) {
    throw new Error("Choose a PNG, JPEG, GIF, or WebP image.");
  }
  if (!Number.isSafeInteger(file.size) || file.size <= 0) {
    throw new Error("The selected image is empty.");
  }
  if (file.size > MAX_IMAGE_UPLOAD_BYTES) {
    throw new Error("Images must be 10 MB or smaller.");
  }
  return contentType as AcceptedImageType;
}

function clampProgress(progress: number): number {
  if (!Number.isFinite(progress)) return 0;
  return Math.min(1, Math.max(0, progress));
}

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.addEventListener("load", () => {
      if (typeof reader.result === "string") resolve(reader.result);
      else reject(new Error("The image could not be read."));
    });
    reader.addEventListener("error", () =>
      reject(reader.error ?? new Error("The image could not be read.")),
    );
    reader.addEventListener("abort", () =>
      reject(new Error("Reading the image was cancelled.")),
    );
    reader.readAsDataURL(file);
  });
}

/**
 * Upload with XMLHttpRequest so progress reflects bytes sent, rather than only
 * the request lifecycle. Convex upload URLs return `{ storageId }` as JSON.
 */
export const uploadToConvexStorage: ImageUploadTransport = (
  uploadUrl,
  file,
  onProgress,
) =>
  new Promise((resolve, reject) => {
    const request = new XMLHttpRequest();
    request.open("POST", uploadUrl);
    request.responseType = "json";
    request.setRequestHeader("Content-Type", file.type);
    request.upload.addEventListener("progress", (event) => {
      if (event.lengthComputable && event.total > 0) {
        onProgress(clampProgress(event.loaded / event.total));
      }
    });
    request.addEventListener("error", () =>
      reject(new Error("The image upload could not reach storage.")),
    );
    request.addEventListener("abort", () =>
      reject(new Error("The image upload was cancelled.")),
    );
    request.addEventListener("load", () => {
      if (request.status < 200 || request.status >= 300) {
        reject(
          new Error(`Image storage rejected the upload (${request.status}).`),
        );
        return;
      }
      let response: unknown = request.response;
      if (typeof response === "string") {
        try {
          response = JSON.parse(response);
        } catch {
          response = null;
        }
      }
      const storageId =
        response && typeof response === "object" && "storageId" in response
          ? (response as { storageId?: unknown }).storageId
          : null;
      if (typeof storageId !== "string" || !storageId) {
        reject(new Error("Storage did not return an image identifier."));
        return;
      }
      onProgress(1);
      resolve(storageId);
    });
    request.send(file);
  });

/**
 * Create an explicit online or offline adapter. Online failures are allowed to
 * surface so callers can retain a retryable node; they never fall back to a
 * data URL. Offline mode deliberately keeps the image inline.
 */
export function createImageUploadAdapter(
  options: ImageUploadAdapterOptions,
): ImageUploadAdapter {
  if (options.mode === "offline") {
    return {
      mode: "offline",
      async upload(file, onProgress) {
        const contentType = validateImageFile(file);
        onProgress?.({ phase: "reading", progress: 0 });
        const src = await (options.readDataUrl ?? readFileAsDataUrl)(file);
        onProgress?.({ phase: "complete", progress: 1 });
        return {
          src,
          storage: "inline",
          imageId: null,
          contentType,
          size: file.size,
        };
      },
    };
  }

  return {
    mode: "online",
    async upload(file, onProgress) {
      const contentType = validateImageFile(file);
      const folioId =
        typeof options.folioId === "function"
          ? options.folioId()
          : options.folioId;
      if (!folioId.trim())
        throw new Error("Choose a folio before adding an image.");

      onProgress?.({ phase: "requesting-url", progress: 0 });
      const { uploadUrl } = await options.client.mutation(
        api.images.generateUploadUrl,
        { contentType, size: file.size },
      );

      const transport = options.transport ?? uploadToConvexStorage;
      const storageId = await transport(uploadUrl, file, (progress) => {
        onProgress?.({
          phase: "uploading",
          progress: 0.05 + clampProgress(progress) * 0.85,
        });
      });

      onProgress?.({ phase: "saving", progress: 0.95 });
      const saved = await options.client.mutation(api.images.saveImage, {
        folioId,
        storageId: storageId as Id<"_storage">,
      });
      onProgress?.({ phase: "complete", progress: 1 });
      return {
        src: saved.url,
        storage: "convex",
        imageId: String(saved.imageId),
        contentType,
        size: file.size,
      };
    },
  };
}

export function imageFilesFromList(
  files: ArrayLike<File> | null | undefined,
): File[] {
  if (!files) return [];
  return Array.from(files).filter((file) =>
    acceptedImageTypes.has(file.type.trim().toLowerCase()),
  );
}

/** Open the native chooser without requiring a file-input in shared markup. */
export function selectImageFiles(multiple = true): Promise<File[]> {
  if (typeof document === "undefined") return Promise.resolve([]);
  return new Promise((resolve) => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ACCEPTED_IMAGE_TYPES.join(",");
    input.multiple = multiple;
    input.hidden = true;
    document.body.append(input);

    const finish = () => {
      const files = imageFilesFromList(input.files);
      input.remove();
      resolve(files);
    };
    input.addEventListener("change", finish, { once: true });
    input.addEventListener("cancel", finish, { once: true });
    input.click();
  });
}

