        let mirrorTimer: ReturnType<typeof setTimeout> | null = null;
        const mirrorDraft = (html: string) => {
          if (mirrorTimer) clearTimeout(mirrorTimer);
          mirrorTimer = setTimeout(() => {
            void syncDraftToLix(store.activeFolioId, html).then(() => {
