          disabled={!hasActive}
          onClick$={() => {
            props.editor?.commands.replaceCurrent(replacement.value);
            revision.value++;
          }}
        >
          Replace
        </button>
        <button
          type="button"
          disabled={count === 0}
          onClick$={() => {
            props.editor?.commands.replaceAll(replacement.value);
            revision.value++;
          }}
