        <label>
          <input
            type="checkbox"
            checked={caseSensitive.value}
            onChange$={(event) => {
              caseSensitive.value = (event.target as HTMLInputElement).checked;
              void updateQuery();
            }}
          />{" "}
          Match case
        </label>
        <label>
          <input
            type="checkbox"
            checked={wholeWord.value}
            onChange$={(event) => {
              wholeWord.value = (event.target as HTMLInputElement).checked;
              void updateQuery();
            }}
          />{" "}
          Whole word
        </label>
        <label>
          <input
            type="checkbox"
            checked={regex.value}
            onChange$={(event) => {
              regex.value = (event.target as HTMLInputElement).checked;
              void updateQuery();
            }}
          />{" "}
          Regular expression
        </label>
      </div>

      {state?.error && (
        <p
          id="find-replace-error"
          role="alert"
          style={{ margin: 0, color: "#9f2d20" }}
        >
          {state.error}
        </p>
      )}
    </section>
  );
});

